    ws=value;session=identity();dialog=node('dialog');dialog.id='advancementAdminDialog';dialog.setAttribute('aria-labelledby','advancementAdminTitle');dialog.style.cssText='box-sizing:border-box;max-width:860px;width:min(94vw,860px);max-height:88vh;overflow:auto;padding:24px;border:1px solid var(--adm-line);border-radius:18px;background:var(--adm-panel);color:var(--adm-text)';
    const title=node('h2','운영 시뮬레이션·초안 지원');title.id='advancementAdminTitle';const nav=node('div');nav.className='adm-filters';nav.style.cssText='display:flex;flex-wrap:wrap;gap:8px';
    nav.append(button('시뮬레이션 원장',ledger),button('실행 시뮬레이션',runtimeMeter),button('초안 지원',support),button('제공자 합의',()=>{leave();navigatePanel('agreement');}),button('운영 준비 근거',readiness),button('연동 준비',operatingPreparation),button('서명 이벤트 샌드박스',sandboxPayments),button('닫기',leave));
    const header=node('div');header.style.cssText='position:sticky;top:0;z-index:2;background:var(--adm-panel);padding-bottom:12px';header.append(title,nav);status=node('p');status.setAttribute('role','status');status.setAttribute('aria-live','polite');body=node('div');body.style.overflowWrap='anywhere';dialog.append(header,status,body);dialog.addEventListener('cancel',leave);document.body.append(dialog);decorate(dialog);dialog.showModal();await ledger();
